import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.CuUVYbLV.js";const k=JSON.parse('{"title":"三步速查","description":"三条命令把 rolebox 跑起来：装插件、建角色、在 harness 里对话，附五条常见排查。","frontmatter":{"title":"三步速查","description":"三条命令把 rolebox 跑起来：装插件、建角色、在 harness 里对话，附五条常见排查。"},"headers":[],"relativePath":"01-Overview/quick-start.md","filePath":"01-Overview/quick-start.md"}'),t={name:"01-Overview/quick-start.md"};function l(n,s,p,d,c,r){return a(),i("div",null,[...s[0]||(s[0]=[o(`<h1 id="三步速查-quick-start" tabindex="-1">三步速查（Quick Start） <a class="header-anchor" href="#三步速查-quick-start" aria-label="Permalink to &quot;三步速查（Quick Start）&quot;">​</a></h1><p>这一页只给最短路径：装、建、跑。每一步为什么这样做、每条输出怎么读，见<a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01 安装并跑通第一个角色</a>；三个 harness 的完整安装矩阵见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>。</p><h2 id="第-1-步-装" tabindex="-1">第 1 步：装 <a class="header-anchor" href="#第-1-步-装" aria-label="Permalink to &quot;第 1 步：装&quot;">​</a></h2><p>opencode 是本页与教程的主线，在它的配置目录里安装插件：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/opencode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rolebox</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，包数量与耗时随 npm 版本、网络环境略有差异）：</span></span>
<span class="line"><span>added 83 packages in 22s</span></span></code></pre></div><p>另外两个 harness 各一行：</p><ul><li>pi：<code>pi install npm:rolebox</code>（想在项目里安装用 <code>pi install -l npm:rolebox</code>）</li><li>dsh：<code>dsh plugin --profile &lt;name&gt; add rolebox</code></li></ul><p>opencode 还必须在配置里声明插件，否则它不会被加载：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~/.config/opencode/opencode.jsonc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rolebox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><h2 id="第-2-步-建" tabindex="-1">第 2 步：建 <a class="header-anchor" href="#第-2-步-建" aria-label="Permalink to &quot;第 2 步：建&quot;">​</a></h2><p>harness 会扫描 <code>&lt;会话工作目录&gt;/rolebox/</code>（存在时优先）或 harness 的全局角色目录里的角色。在 <code>~/rolebox-lab</code> 下建一个练习项目，再创建角色：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab/rolebox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab/rolebox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code-reviewer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到：</span></span>
<span class="line"><span>✓ Created standard role at /Users/&lt;你&gt;/rolebox-lab/rolebox/code-reviewer</span></span>
<span class="line"><span>Run \`rolebox sync opencode\` to deploy</span></span></code></pre></div><p><code>-y</code> 跳过交互向导并使用默认的 <code>standard</code> 模板，生成 <code>role.yaml</code>、<code>PROMPT.md</code>、<code>skills/</code> 与 <code>functions/</code>。</p><h2 id="第-3-步-跑" tabindex="-1">第 3 步：跑 <a class="header-anchor" href="#第-3-步-跑" aria-label="Permalink to &quot;第 3 步：跑&quot;">​</a></h2><p>从 <code>~/rolebox-lab</code> 启动 harness——会话工作目录决定它去哪个 <code>rolebox/</code> 目录找角色：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，随 harness 与版本略有差异）：</span></span>
<span class="line"><span>代理列表里出现 code-reviewer</span></span></code></pre></div><p>选中 <code>code-reviewer</code> 就能对话。它现在只会照模板回答，因为 <code>PROMPT.md</code> 还是脚手架里的 <code>TODO</code>——这正是教程第 02 章要改的。</p><h2 id="常见排查" tabindex="-1">常见排查 <a class="header-anchor" href="#常见排查" aria-label="Permalink to &quot;常见排查&quot;">​</a></h2><p><strong>harness 里看不到角色。</strong> 角色目录按「会话工作目录下的 <code>rolebox/</code>」优先解析。确认 <code>ls ~/rolebox-lab/rolebox/code-reviewer/role.yaml</code> 能找到文件，从 <code>~/rolebox-lab</code> 启动 harness，改动之后重启一次。</p><p><strong><code>rolebox sync</code> 没有部署我 <code>init</code> 的角色。</strong> 正常。<code>sync</code> 面向从注册中心安装的角色：<code>rolebox install &lt;角色名&gt;</code> 把角色登记进安装锁文件，<code>rolebox sync &lt;harness&gt;</code> 部署锁文件里的条目；<code>rolebox init</code> 生成的本地角色不经过锁文件，放进角色目录就已经生效。还没装过注册中心角色时，这两条命令的输出是：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（还没有安装过注册中心角色时）：</span></span>
<span class="line"><span>No roles installed. Run \`rolebox install &lt;role&gt;\` to get started.</span></span>
<span class="line"><span>Synced 0 roles to opencode</span></span></code></pre></div><p><strong><code>rolebox: command not found</code>。</strong> 按上面的方式安装时，包只存在于 harness 配置目录的 <code>node_modules/</code> 下，跨目录不可见；在该目录里用 <code>npx rolebox &lt;子命令&gt;</code> 调用，或按<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a>全局安装。</p><p><strong>插件装了但没生效（opencode）。</strong> 检查 <code>~/.config/opencode/opencode.jsonc</code> 里有 <code>&quot;plugin&quot;: [&quot;rolebox&quot;]</code>，保存后重启 harness。</p><p><strong><code>role.yaml</code> 报解析错误。</strong> 用空格缩进（不支持 Tab）；<code>skills</code> 与 <code>functions</code> 是字符串数组；字段语义见<a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01 安装并跑通第一个角色</a>——同样的三步，逐步讲清每条输出</li><li><a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>——pi 与 dsh 的安装命令、配置目录与环境变量覆盖</li><li><a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a>——写出完整的 <code>role.yaml</code></li></ul>`,30)])])}const b=e(t,[["render",l]]);export{k as __pageData,b as default};
